// IsSystemVariable reports whether name, in any case, is a system variable of a supported MariaDB
// release or of a plugin MariaDB packages.
func IsSystemVariable(name string) bool {
	_, ok := systemVariables[strings.ToLower(name)]
	return ok
}

// UnknownSystemVariable returns the first assignment under n that sets a name as a system
// variable while a stored program is parsed (Assignment.SystemVariable) when no supported
// release has the variable, which MariaDB refuses as it parses the program (1193,
// ER_UNKNOWN_SYSTEM_VARIABLE), or nil.
func UnknownSystemVariable(n nodes.Node) *nodes.Assignment {
	var found *nodes.Assignment
	nodes.Inspect(n, func(n nodes.Node) bool {
		if found != nil {
			return false
		}
		if a, ok := n.(*nodes.Assignment); ok && a.SystemVariable && !IsSystemVariable(a.Column.Column) {
			found = a
		}
		return found == nil
	})
	return found
}
